def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def move_away(a, b):
        return [sgn(a[0] - b[0]), sgn(a[1] - b[1])]

    def valid_move(m):
        return isinstance(m, (list, tuple)) and len(m) >= 2 and m[0] in (-1, 0, 1) and m[1] in (-1, 0, 1)

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_toward(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = corners[0]
        best = -1
        for c in corners:
            d = dist(c, opp_pos)
            if d > best:
                best = d
                target = c
        return move_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best_move = [0, 0]
        best_score = None
        for t in targets:
